package com.example.starter.weigh;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 检测记录领域行：车辆过磅产生的称重判定数据。
 */
public record WeighRecord(
        Long id,
        String requestId,
        String fingerprint,
        String plateNo,
        String stationId,
        Instant weighedAt,
        String axleType,
        String weighType,
        int totalWeightKg,
        int limitWeightKg,
        BigDecimal overRate,
        boolean overLimit,
        boolean authoritative,
        boolean lateEvidence) {
}

package com.example.starter.weigh;

import java.time.Instant;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Positive;

/**
 * 过磅请求：生成检测记录，requestId 幂等。
 */
public record WeighRecordRequest(
        @NotBlank String requestId,
        @NotBlank String plateNo,
        @NotBlank String stationId,
        @NotNull Instant weighedAt,
        @NotBlank String axleType,
        @NotBlank @Pattern(regexp = "DYNAMIC|STATIC", message = "must be DYNAMIC or STATIC") String weighType,
        @Positive int totalWeightKg) {
}

package com.example.starter.weigh;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 过磅响应：deduplicated 表示命中“车牌+检测站+过磅时刻+称重方式”去重，
 * idempotentReplay 表示同 requestId 同参数重放返回首次结果。
 */
public record WeighRecordResponse(
        long id,
        String requestId,
        String plateNo,
        String stationId,
        Instant weighedAt,
        String axleType,
        String weighType,
        int totalWeightKg,
        int limitWeightKg,
        BigDecimal overRate,
        boolean overLimit,
        boolean authoritative,
        boolean lateEvidence,
        boolean deduplicated,
        boolean idempotentReplay) {

    static WeighRecordResponse of(WeighRecord r, boolean deduplicated, boolean idempotentReplay) {
        return new WeighRecordResponse(r.id(), r.requestId(), r.plateNo(), r.stationId(), r.weighedAt(),
                r.axleType(), r.weighType(), r.totalWeightKg(), r.limitWeightKg(), r.overRate(),
                r.overLimit(), r.authoritative(), r.lateEvidence(), deduplicated, idempotentReplay);
    }
}

